"""Only a new owned child changes its own soft NOFILE; the parent never does."""
import json,os,resource,subprocess,sys

CHILD='''import errno,json,os,resource,socket,sys
request=json.load(sys.stdin);before=resource.getrlimit(resource.RLIMIT_NOFILE);phases=[]
try:
 for limit in (request['low'],request['high']):
  resource.setrlimit(resource.RLIMIT_NOFILE,(limit,before[1]));held=[];error=None
  try:
   for _ in range(256):
    try:held.append(os.open('/dev/null',os.O_RDONLY))
    except OSError as failure:error=failure.errno;break
   if error!=errno.EMFILE:raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: expected real EMFILE not observed')
   count=len(held);os.close(held.pop());recovered=os.open('/dev/null',os.O_RDONLY);os.close(recovered)
  finally:
   for fd in held:os.close(fd)
  active=[];accepted=0;rejected=0;created=0
  try:
   for _ in range(request['capacity']+2):
    pair=socket.socketpair();created+=1
    if len(active)>=request['capacity']:rejected+=1;pair[0].close();pair[1].close()
    else:active.append(pair);accepted+=1
  finally:
   for pair in active:pair[0].close();pair[1].close()
  phases.append({'soft_limit':resource.getrlimit(resource.RLIMIT_NOFILE)[0],'opened_descriptors':count,'emfile_errno':error,'one_closed_slot_reopened':True,'socket_pairs_created':created,'accepted_connections':accepted,'application_rejected':rejected,'all_resources_closed':True})
finally:resource.setrlimit(resource.RLIMIT_NOFILE,before)
print(json.dumps({'pid':os.getpid(),'uid':os.getuid(),'before_limits':list(before),'after_limits':list(resource.getrlimit(resource.RLIMIT_NOFILE)),'phases':phases}))
'''

def native(low,high,capacity):
    if any(type(x)is not int for x in(low,high,capacity))or not 16<=low<high<=128 or not 1<=capacity<=4:raise ValueError('invalid owned FD plan')
    before=(os.getuid(),os.environ.get('HOME'),os.environ.get('PATH'),resource.getrlimit(resource.RLIMIT_NOFILE))
    hard=before[-1][1]
    if hard!=resource.RLIM_INFINITY and hard<high:raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: owned hard NOFILE too small')
    proc=subprocess.Popen([sys.executable,'-B','-c',CHILD],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    try:stdout,stderr=proc.communicate(json.dumps({'low':low,'high':high,'capacity':capacity}).encode(),timeout=5)
    except subprocess.TimeoutExpired:proc.kill();proc.communicate(timeout=2);raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: owned FD child deadline')
    assert before==(os.getuid(),os.environ.get('HOME'),os.environ.get('PATH'),resource.getrlimit(resource.RLIMIT_NOFILE))
    if proc.returncode!=0:raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: '+stderr.decode(errors='replace'))
    row=json.loads(stdout)
    if row['pid']!=proc.pid or row['uid']!=1000:raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: owned FD child identity mismatch')
    row.update(exit_code=proc.returncode,reaped=True,parent_identity_environment_NOFILE_unchanged=True);print('OWNED_FD_PROBE:'+json.dumps(row),flush=True);return row

