    if a is None or b is None:return a is b
    if type(a)in(int,float)and type(b)in(int,float):return a==b
    if isinstance(a,dict)and isinstance(b,dict):return set(a)==set(b)and all(equal(a[k],v)for k,v in b.items())
    if isinstance(a,list)and isinstance(b,list):return len(a)==len(b)and all(equal(x,y)for x,y in zip(a,b))
    return type(a)is type(b)and a==b

for low,high,cap in [(15,64,2),(32,32,2),(32,129,2),(True,64,2),(32,64,False),(32,64,0),(32,64,5)]:
