    assert gain>0 and a['emfile_errno']==24 and b['emfile_errno']==24 and a['soft_limit']==low and b['soft_limit']==high
    assert raw['before_limits']==raw['after_limits']and raw['reaped']and raw['exit_code']==0 and raw['parent_identity_environment_NOFILE_unchanged']is True
    for phase in raw['phases']:
        assert phase['one_closed_slot_reopened']is True and phase['all_resources_closed']is True
        assert phase['socket_pairs_created']==capacity+2 and phase['accepted_connections']==capacity and phase['application_rejected']==2
    expected={'schema':1,'native':raw,'descriptor_gain':gain,'accepted_gain':accepted_gain,'both_hit_EMFILE':True,'application_limit_still_applies':True,'fd_is_total_service_capacity':False,'scope':'owned_process_FD_and_application_admission_only'}
    assert equal(actual,expected),'report confuses actual descriptor headroom with application/service capacity'
    print('NATIVE_FD_CAPACITY_VERIFIED:'+json.dumps({'low':low,'high':high,'capacity':capacity,'descriptor_gain':gain,'accepted_gain':accepted_gain,'actual':actual}),flush=True)
